"""Questions for error analysis, generated by crossing the dimensions in `evals/questions/grid.yaml`.

Intent is assigned round-robin so every intent gets the same share; window, data state, metric,
template and persona are drawn from a seeded RNG, so a batch is reproducible. `paraphrase`
optionally rewrites each templated question in natural words with a model (synthetic context
only), keeping ids and tags.
"""
from __future__ import annotations

import hashlib
import random
from collections.abc import Callable
from pathlib import Path

import yaml

GRID = Path("evals/questions/grid.yaml")
SEED = 20261030


def load_grid(path: Path = GRID) -> dict:
    return yaml.safe_load(Path(path).read_text(encoding="utf-8"))


def expand(grid: dict, n: int, seed: int = SEED) -> list[dict]:
    rng = random.Random(seed)
    dims = grid["dimensions"]
    items = []
    for i in range(n):
        intent = dims["intent"][i % len(dims["intent"])]
        data_state = rng.choice(dims["data_state"])
        window = rng.choice(dims["window"])
        persona = rng.choice(dims["persona"])
        metric = rng.choice(grid["metrics"][data_state])
        base = rng.choice(grid["templates"][intent]).format(metric=metric, window=window)
        short = f"{metric}, {window}?" if "{metric}" in "".join(grid["templates"][intent]) else base
        question = grid["personas"][persona].format(q=base, q_short=short)
        digest = hashlib.sha256(f"{seed}|{i}|{question}".encode()).hexdigest()[:8]
        items.append({"id": f"q-{i:03d}-{digest}", "question": question,
                      "tags": {"intent": intent, "window": window, "data_state": data_state,
                               "persona": persona}})
    return items


PARAPHRASE = ("Rewrite this question the way a person would type it to a health app, keeping "
              "its meaning, tone and any numbers. Reply with the question only.\n\n{q}")


def paraphrase(items: list[dict], generate: Callable[[str], str]) -> list[dict]:
    out = []
    for item in items:
        text = generate(PARAPHRASE.format(q=item["question"])).strip()
        out.append({**item, "question": text or item["question"], "template": item["question"]})
    return out


def write_batch(items: list[dict], path: Path) -> Path:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(yaml.safe_dump({"questions": items}, sort_keys=False, allow_unicode=True),
                    encoding="utf-8")
    return path
